package main

import "fmt"

func main() {
  var i int = 8 // 变量赋值
  fmt.Println(i)  // 输出
}

package main

import "fmt"

func main() {
  // 一次性定义多个变量且赋值
  var i, j int = 8, 42
  fmt.Println(i) 
  fmt.Println(j)
}

package main

import "fmt"

func main() {
  // 没有声明变量类型
  var i, j = 8, 42
  fmt.Println(i) 
  fmt.Println(j)
}

package main

import "fmt"

func main() {
  i := 8
  fmt.Println(i)
}
